    mb.addSphere(hx, headY, hz, 2.5, 2.3, 2.5, 10, 12, bodyColor, TexId.SOLID, 0.65);
    mb.addCone(hx + rx * 1.45, headY + 1.6, hz + rz * 1.45, 0.9, 2.2, 8, bodyColor, TexId.SOLID, 0.5);
    mb.addCone(hx - rx * 1.45, headY + 1.6, hz - rz * 1.45, 0.9, 2.2, 8, bodyColor, TexId.SOLID, 0.5);
