          x0: p0.x,
          y0: p0.y,
          x1: p1.x,
          y1: p1.y,
          x2: p2.x,
          y2: p2.y,
          depth: (p0.w + p1.w + p2.w) / 3,
          fill: a < 0.99 ? `rgba(${r},${g2},${b},${a.toFixed(2)})` : `rgb(${r},${g2},${b})`
