      ctx.save();
      ctx.globalAlpha = 1 - p;
      ctx.fillStyle = "#121218";
      ctx.fillRect(d.bounds.x, d.bounds.y, d.bounds.width, Math.max(1, Math.round(d.bounds.height * (1 - p))));
      ctx.restore();
