  let band1 = smoothstep(-0.16, -0.09, ndl);
  let band2 = smoothstep(0.32, 0.39, ndl);
  var toonBand = mix(shadowTone, midTone, band1);
  toonBand = mix(toonBand, litTone, band2);
  toonBand = toonBand + vec3<f32>(ambientBoost);

