  let V = normalize(scene.cameraPosAndTime.xyz - in.worldPos);
  let H = normalize(sunDir + V);
  let ndh = max(0.0, dot(N, H));
  let spec = smoothstep(0.89, 0.93, ndh) * step(0.15, ndl) * 0.16;

